//! r39:el-arrange — a track's own icon (the owner, 2026-11-09; ADR 0113): an icon of the
//! user's choice before the track's name, to find it at a glance, beside the type icon its
//! instrument gives. The project keeps its id (`Track::glyph`); this file is the library,
//! how each icon is drawn, and the picker (search, *None*, the recent row, the families).
//!
//! **The library** is the icon family's set 6 (round 39, `icons`; the owner's 17 families,
//! 316 icons, `docs/round39/design/icons/set6-additions.md`), generated by
//! `tools/icons/track_glyphs.js` into `assets/icons/tracks.txt`: the families in the
//! picker's order, each icon's English and Spanish names and its search words, and its
//! drawing for every device size it is built for (12–36 px; never one drawing scaled,
//! ADR 0108). An id this build does not know is drawn as none, and kept.

use crate::app::CantusApp;
use crate::i18n::{t, Locale};
use crate::kit::brush::Brush;
use crate::kit::color::mix;
use crate::kit::icons::Inks;
use crate::kit::{self, Style};
use crate::views::arrangement::slate::{self, W};
use cantus_core::{ArrangeCommand, Command, TrackId};
use egui::{pos2, vec2, Align2, Color32, Id, Pos2, Rect, Sense};
use std::collections::HashMap;
use std::sync::OnceLock;

/// The device sizes every icon is drawn for (the arrangement's 14/16, the mixer's 12/14,
/// the picker's 24, and each at 125 % and 150 %).
pub const SIZES: [u16; 10] = [12, 14, 15, 16, 18, 20, 21, 24, 30, 36];

const DATA: &str = include_str!("../../assets/icons/tracks.txt");

/// One icon of the library.
#[derive(Debug)]
pub struct Icon {
    pub id: &'static str,
    pub en: &'static str,
    pub es: &'static str,
    /// The search words, comma-separated (both languages, and the makers' model names
    /// that never become labels).
    pub words: &'static str,
    drawings: [Option<&'static str>; SIZES.len()],
    /// Everything search reads, folded (lower case, no accents).
    folded: String,
}

/// A row of the picker: a family, or a family's sub-row.
#[derive(Debug)]
pub struct Section {
    /// The family's id (`drums`, `guitars_and_basses`…).
    pub family: &'static str,
    /// The sub-row's id, under its family.
    pub sub: Option<&'static str>,
    /// The title's i18n key.
    pub key: String,
    pub icons: Vec<u16>,
}

/// The whole library.
#[derive(Debug)]
pub struct Library {
    pub icons: Vec<Icon>,
    pub sections: Vec<Section>,
    by_id: HashMap<&'static str, u16>,
    /// An icon's name in one family where it differs (the bass clef is the synth bass's
    /// drawing): (family, id) → (en, es).
    labels: HashMap<(&'static str, &'static str), (&'static str, &'static str)>,
}

/// An icon a track can carry.
#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
pub struct TrackGlyph {
    pub id: &'static str,
    index: u16,
}

impl TrackGlyph {
    pub fn icon(self) -> &'static Icon {
        &library().icons[usize::from(self.index)]
    }

    /// Its name in the interface's language.
    pub fn name(self) -> &'static str {
        let i = self.icon();
        match crate::i18n::locale() {
            Locale::En => i.en,
            Locale::Es => i.es,
        }
    }

    /// Its name in `family` (where the family names it otherwise), in the interface's
    /// language.
    pub fn name_in(self, family: &str) -> &'static str {
        let lib = library();
        let Some(&(en, es)) = lib
            .labels
            .iter()
            .find(|((f, id), _)| *f == family && *id == self.id)
            .map(|(_, v)| v)
        else {
            return self.name();
        };
        match crate::i18n::locale() {
            Locale::En => en,
            Locale::Es => es,
        }
    }
}

/// Lower case without accents: what search compares.
pub fn fold(s: &str) -> String {
    s.chars()
        .flat_map(char::to_lowercase)
        .map(|c| match c {
            'á' | 'à' | 'â' | 'ä' | 'ã' => 'a',
            'é' | 'è' | 'ê' | 'ë' => 'e',
            'í' | 'ì' | 'î' | 'ï' => 'i',
            'ó' | 'ò' | 'ô' | 'ö' | 'õ' => 'o',
            'ú' | 'ù' | 'û' | 'ü' => 'u',
            'ñ' => 'n',
            'ç' => 'c',
            c => c,
        })
        .collect()
}

fn parse() -> Library {
    let mut lib = Library {
        icons: Vec::new(),
        sections: Vec::new(),
        by_id: HashMap::new(),
        labels: HashMap::new(),
    };
    // Rows reference ids before their words are read: keep them by name until the end.
    let mut rows: Vec<(&'static str, Option<&'static str>, Vec<&'static str>)> = Vec::new();
    for line in DATA.lines() {
        let f: Vec<&'static str> = line.split('\t').collect();
        match f.as_slice() {
            ["F", fam, _] => rows.push((fam, None, Vec::new())),
            ["S", sub, _] => {
                let fam = rows.last().map_or("", |r| r.0);
                rows.push((fam, Some(sub), Vec::new()));
            }
            ["I", id] => {
                if let Some(r) = rows.last_mut() {
                    r.2.push(id);
                }
            }
            ["W", id, en, es, words] => {
                let folded = fold(&format!("{id} {en} {es} {words}"));
                let i = lib.icons.len() as u16;
                lib.by_id.insert(id, i);
                lib.icons.push(Icon {
                    id,
                    en,
                    es,
                    words,
                    drawings: [None; SIZES.len()],
                    folded,
                });
            }
            ["L", fam, id, en, es] => {
                lib.labels.insert((fam, id), (en, es));
            }
            ["D", id, size, body] => {
                let (Some(&i), Ok(size)) = (lib.by_id.get(id), size.parse::<u16>()) else {
                    continue;
                };
                if let Some(k) = SIZES.iter().position(|s| *s == size) {
                    lib.icons[usize::from(i)].drawings[k] = Some(body);
                }
            }
            _ => {}
        }
    }
    for (fam, en_es) in lib.labels.iter() {
        if let Some(&i) = lib.by_id.get(fam.1) {
            let more = fold(&format!(" {} {}", en_es.0, en_es.1));
            lib.icons[usize::from(i)].folded.push_str(&more);
        }
    }
    for (family, sub, ids) in rows {
        let key = format!("arrange.glyph.family.{}", sub.unwrap_or(family));
        let icons = ids
            .iter()
            .filter_map(|id| lib.by_id.get(id).copied())
            .collect();
        lib.sections.push(Section {
            family,
            sub,
            key,
            icons,
        });
    }
    lib
}

/// The library, read once.
pub fn library() -> &'static Library {
    static LIB: OnceLock<Library> = OnceLock::new();
    LIB.get_or_init(parse)
}

/// The ids el-arrange's first build stored before the library landed, and the icon each
/// is now (the others are kept and drawn as none).
const RENAMED: [(&str, &str); 6] = [
    ("drums", "drumkit"),
    ("vocal", "mic"),
    ("keyboard", "midikeyboard"),
    ("click", "metronome-track"),
    ("mixer", "bus"),
    ("record", "mic"),
];

/// The library's icon of id `id`.
pub fn by_id(id: &str) -> Option<TrackGlyph> {
    let lib = library();
    let id = RENAMED
        .iter()
        .find(|(old, _)| *old == id)
        .map_or(id, |(_, new)| *new);
    lib.by_id.get(id).map(|&index| TrackGlyph {
        id: lib.icons[usize::from(index)].id,
        index,
    })
}

fn glyph(index: u16) -> TrackGlyph {
    TrackGlyph {
        id: library().icons[usize::from(index)].id,
        index,
    }
}

/// Every icon, in the picker's order, once.
pub fn all() -> impl Iterator<Item = TrackGlyph> {
    (0..library().icons.len() as u16).map(glyph)
}

/// The icon a track carries, if it carries one this build can draw (the helper the mixer's
/// strip head and the clip browser call too).
pub fn track_icon(app: &CantusApp, track: TrackId) -> Option<TrackGlyph> {
    app.project()
        .track(track)
        .and_then(|t| t.glyph.as_deref())
        .and_then(by_id)
}

/// The icons whose names (English or Spanish), id or search words hold every word of
/// `search`, accents and case aside; the names that begin with it first.
pub fn matching(search: &str) -> Vec<TrackGlyph> {
    let q = fold(search.trim());
    let words: Vec<&str> = q.split_whitespace().collect();
    if words.is_empty() {
        return all().collect();
    }
    let lib = library();
    let mut found: Vec<(u8, u16)> = lib
        .icons
        .iter()
        .enumerate()
        .filter(|(_, i)| words.iter().all(|w| i.folded.contains(w)))
        .map(|(n, i)| {
            let (en, es) = (fold(i.en), fold(i.es));
            let rank = if en == q || es == q {
                0
            } else if en.starts_with(&q) || es.starts_with(&q) {
                1
            } else if i.words.split(',').any(|w| fold(w.trim()) == q) {
                2
            } else {
                3
            };
            (rank, n as u16)
        })
        .collect();
    found.sort_by_key(|(rank, _)| *rank);
    found.into_iter().map(|(_, n)| glyph(n)).collect()
}

/// The drawn size for a box `px` device pixels high: the largest that fits, or the least.
pub fn size_for(px: f32) -> u16 {
    SIZES
        .iter()
        .rev()
        .copied()
        .find(|s| f32::from(*s) <= px + 0.5)
        .unwrap_or(SIZES[0])
}

/// The drawing of `g` at `size` device pixels, if it has one.
pub fn drawing(g: TrackGlyph, size: u16) -> Option<&'static str> {
    let k = SIZES.iter().position(|s| *s == size)?;
    g.icon().drawings[k]
}

/// Paint `g` centred in `rect` in `inks`, from its drawing for the box's height on the
/// device, on the device's pixel grid.
pub fn paint_with(b: &mut Brush, rect: Rect, g: TrackGlyph, inks: &Inks) -> bool {
    let ppp = b.ppp();
    let size = size_for(rect.height().min(rect.width()) * ppp);
    let Some(body) = drawing(g, size) else {
        return false;
    };
    let side = f32::from(size) / ppp;
    let snap = |v: f32| (v * ppp).round() / ppp;
    let at = Rect::from_min_size(
        pos2(
            snap(rect.center().x - side * 0.5),
            snap(rect.center().y - side * 0.5),
        ),
        egui::Vec2::splat(side),
    );
    let key = kit::cache::key(("track39", g.id, size, *inks));
    let px = usize::from(size);
    let Some(uv) = b.layer(key, px, px, |pix| {
        kit::icons::raster(&kit::icons::document(body, size, inks), pix)
    }) else {
        return false;
    };
    b.layer_quad(at, uv, 1.0);
    true
}

/// The inks of an icon in `main` on a ground `cut` (its second ink half-way between).
pub fn inks(s: &Style, main: Color32, cut: Color32) -> Inks {
    Inks {
        main,
        second: mix(main, cut, 0.45),
        rec: s.t.danger,
        cut,
    }
}

/// Draw `g` in `rect` with `inks` on `p`.
pub fn paint(p: &egui::Painter, rect: Rect, g: TrackGlyph, inks: &Inks) {
    kit::with_brush(p, |b| {
        paint_with(b, rect, g, inks);
    });
}

/// How many icons the recent row keeps.
pub const RECENT: usize = 8;

/// Set a track's own icon (one undo step; nothing when it is already that). A chosen icon
/// goes to the front of the recent row (a preference of this machine).
pub fn set(app: &mut CantusApp, track: TrackId, glyph: Option<&str>) {
    if let Some(id) = glyph {
        let r = &mut app.settings.track_icons_recent;
        if r.first().map(String::as_str) != Some(id) {
            r.retain(|x| x != id);
            r.insert(0, id.to_string());
            r.truncate(RECENT);
            app.store_settings();
        }
    }
    let now = app.project().track(track).and_then(|t| t.glyph.clone());
    if now.as_deref() == glyph {
        return;
    }
    app.exec(Command::Arrange(ArrangeCommand::SetTrackGlyph {
        track,
        glyph: glyph.map(str::to_string),
    }));
}

/// The recent row: the icons chosen last on this machine, newest first.
pub fn recent(app: &CantusApp) -> Vec<TrackGlyph> {
    app.settings
        .track_icons_recent
        .iter()
        .filter_map(|id| by_id(id))
        .take(RECENT)
        .collect()
}

/// The picker while it is open: for which track, where, the search so far and the scroll.
#[derive(Clone, Debug, Default)]
pub struct Picker {
    pub open: Option<(TrackId, Pos2)>,
    pub search: String,
    /// How far the families are scrolled, in points.
    pub scroll: f32,
    /// The pass it opened in (that click is not a click away from it).
    opened: u64,
    /// Each cell drawn last frame, and *None*'s (tests aim with it). A cell of the recent
    /// row comes before the families' cells.
    pub drawn: Vec<(Option<&'static str>, Rect)>,
}

impl Picker {
    /// Open the picker for `track` at `at`.
    pub fn open_for(&mut self, track: TrackId, at: Pos2, ctx: &egui::Context) {
        self.open = Some((track, at));
        self.search.clear();
        self.scroll = 0.0;
        self.opened = ctx.cumulative_pass_nr();
    }
}

// The picker's measures (des-icons' picker sheet, points at 100 %).
const WIDTH: f32 = 300.0;
const PAD: f32 = 12.0;
const CELL: f32 = 32.0;
const GAP: f32 = 2.0;
const COLS: usize = 8;
const VIEW: f32 = 520.0;

/// What the picker's scrolled body holds, top to bottom.
enum Line {
    Title(String, bool),
    Cells(Vec<TrackGlyph>),
    Empty,
}

fn lines(search: &str) -> Vec<Line> {
    let mut out = Vec::new();
    if search.trim().is_empty() {
        for sec in &library().sections {
            out.push(Line::Title(t(&sec.key), sec.sub.is_some()));
            let row: Vec<TrackGlyph> = sec.icons.iter().map(|&i| glyph(i)).collect();
            for chunk in row.chunks(COLS) {
                out.push(Line::Cells(chunk.to_vec()));
            }
        }
    } else {
        let found = matching(search);
        if found.is_empty() {
            out.push(Line::Empty);
        }
        for chunk in found.chunks(COLS) {
            out.push(Line::Cells(chunk.to_vec()));
        }
    }
    out
}

fn line_height(l: &Line) -> f32 {
    match l {
        Line::Title(_, false) => 18.0,
        Line::Title(_, true) => 14.0,
        Line::Cells(_) => CELL + GAP,
        Line::Empty => 28.0,
    }
}

/// One icon's cell: the raised well under the pointer, the accent's when chosen.
#[allow(clippy::too_many_arguments)]
fn cell(
    ui: &egui::Ui,
    b: &mut Brush,
    s: &Style,
    ink: &slate::Ink,
    r: Rect,
    g: TrackGlyph,
    on: bool,
    hovered: bool,
) {
    let ground = if on {
        mix(ink.raised, ink.accent, 0.2)
    } else if hovered {
        ink.well_hi
    } else {
        ink.raised
    };
    if on || hovered {
        b.rrect(b.snap_rect(r), s.s(4.0), kit::Fill::Solid(ground));
    }
    if on {
        b.rrect_stroke(b.snap_rect(r), s.s(4.0), s.s(1.0), ink.accent);
    }
    let main = if on {
        ink.accent
    } else if hovered {
        ink.ink1
    } else {
        ink.ink2
    };
    let mut inks = inks(s, main, ground);
    inks.second = if on {
        mix(ink.accent, ground, 0.45)
    } else if hovered {
        ink.ink2
    } else {
        ink.ink3
    };
    let _ = ui;
    paint_with(b, r.shrink(s.s(4.0)), g, &inks);
}

/// The picker's popover, when open: its title, a search field, *None*, the recent row and
/// the families (scrolled), or what search found.
pub fn show(app: &mut CantusApp, ctx: &egui::Context) {
    let Some((track, at)) = app.arrangement.glyphs.open else {
        return;
    };
    let Some(track_name) = app.project().track(track).map(|t| t.name.clone()) else {
        app.arrangement.glyphs.open = None;
        return;
    };
    let s = Style::current();
    let ink = slate::Ink::of(&s);
    let chosen = app.project().track(track).and_then(|t| t.glyph.clone());
    let chosen = chosen.as_deref().and_then(by_id).map(|g| g.id);
    let recent = recent(app);
    let mut close = false;
    let mut pick: Option<Option<&'static str>> = None;
    let mut drawn = Vec::new();
    let mut hovered_name: Option<&'static str> = None;
    let screen = ctx.content_rect();
    let searching = !app.arrangement.glyphs.search.trim().is_empty();
    // The head (title, field, None), the recent row, the view, the foot.
    let head = 22.0 + 32.0 + CELL + 8.0;
    let rec_h = if searching || recent.is_empty() {
        0.0
    } else {
        16.0 + CELL + 8.0
    };
    let foot = 1.0 + 8.0 + 24.0;
    let fixed = PAD + head + rec_h + 9.0 + foot;
    let view_h = VIEW.min((screen.height() / s.k - fixed - 16.0).max(CELL * 3.0));
    let (w, h) = (s.s(WIDTH), s.s(fixed + view_h));
    // Inside the window: the popover moves up and left as far as it must.
    let at = pos2(
        at.x.min(screen.right() - w - s.s(4.0)).max(screen.left()),
        at.y.min(screen.bottom() - h - s.s(4.0)).max(screen.top()),
    );
    // r39:fix2 — the click that closes the picker is the picker's, as the instrument
    // picker's scrim takes its own: a catcher over the window, under the popover, so a
    // click away closes it and lands on nothing beneath (on the desk's empty strips it
    // made strips, and Undo then took those back instead of the icon).
    egui::Area::new(Id::new("arrange-glyph-catcher"))
        .order(egui::Order::Middle)
        .fixed_pos(screen.min)
        .show(ctx, |ui| {
            let _ = ui.allocate_exact_size(screen.size(), Sense::click_and_drag());
        });
    let area = egui::Area::new(Id::new("arrange-glyph-picker"))
        .order(egui::Order::Foreground)
        .fixed_pos(at)
        .show(ctx, |ui| {
            let (rect, _) = ui.allocate_exact_size(vec2(w, h), Sense::hover());
            kit::with_brush(ui.painter(), |b| {
                kit::menu::paint(b, rect, &s, &[], None);
            });
            let left = rect.left() + s.s(PAD);
            let right = rect.right() - s.s(PAD);
            let mut y = rect.top() + s.s(PAD);
            kit::with_brush(ui.painter(), |b| {
                let row = Rect::from_min_max(pos2(left, y), pos2(right, y + s.s(16.0)));
                let title = t("arrange.glyph.title");
                let tw = slate::width(ui.ctx(), &title, W::Medium, 13.0, &s);
                let _ = slate::say(
                    b,
                    row,
                    &title,
                    W::Medium,
                    13.0,
                    ink.ink1,
                    Align2::LEFT_CENTER,
                    &s,
                );
                let name = Rect::from_min_max(pos2(left + tw + s.s(12.0), y), row.right_bottom());
                let _ = slate::say(
                    b,
                    name,
                    &track_name,
                    W::Regular,
                    12.0,
                    ink.ink3,
                    Align2::RIGHT_CENTER,
                    &s,
                );
            });
            y += s.s(22.0);
            let field = Rect::from_min_max(pos2(left, y), pos2(right, y + s.s(24.0)));
            let hint = t("arrange.glyph.search");
            // The keyboard goes to the search when the picker opens: type, then Enter.
            let out = kit::field::Field::new(Id::new("arrange-glyph-search"))
                .hint(&hint)
                .opens_when_shown()
                .show(ui, field, &mut app.arrangement.glyphs.search);
            let enter = ui.input(|i| i.key_pressed(egui::Key::Enter));
            match out.event {
                Some(kit::field::Event::Cancel) => close = true,
                Some(kit::field::Event::Commit) if searching && enter => {
                    // Enter takes the first icon found (a click elsewhere only commits).
                    if let Some(g) = matching(&app.arrangement.glyphs.search).first() {
                        pick = Some(Some(g.id));
                    }
                }
                _ => {}
            }
            if out.resp.changed() {
                app.arrangement.glyphs.scroll = 0.0;
            }
            y += s.s(32.0);
            let none = Rect::from_min_size(pos2(left, y), vec2(s.s(2.0 * CELL + GAP), s.s(CELL)));
            let r = ui.interact(none, Id::new("arrange-glyph-none"), Sense::click());
            drawn.push((None, none));
            let st = kit::State::of(&r, chosen.is_none());
            kit::with_brush(ui.painter(), |b| {
                kit::cap::toolbar_key(b, none, &s, st, kit::cap::KeyFace::Text(""));
                // The word as the sheet sets it ("None", Regular 12, ink 2), not the key's
                // small capitals.
                let _ = slate::say(
                    b,
                    none,
                    &t("arrange.glyph.none"),
                    W::Regular,
                    12.0,
                    ink.ink2,
                    Align2::CENTER_CENTER,
                    &s,
                );
                let why = Rect::from_min_max(
                    pos2(none.right() + s.s(6.0), none.top()),
                    pos2(right, none.bottom()),
                );
                let _ = slate::say(
                    b,
                    why,
                    &t("arrange.glyph.none_tip"),
                    W::Regular,
                    10.0,
                    ink.ink3,
                    Align2::LEFT_CENTER,
                    &s,
                );
            });
            if r.hovered() {
                hovered_name = Some("");
                kit::hint::set_text(
                    ui.ctx(),
                    &t("arrange.glyph.none_tip"),
                    "",
                    kit::hint::Caps::NONE,
                );
            }
            if r.clicked() {
                pick = Some(None);
            }
            y += s.s(CELL + 8.0);
            if rec_h > 0.0 {
                kit::with_brush(ui.painter(), |b| {
                    let row = Rect::from_min_max(pos2(left, y), pos2(right, y + s.s(14.0)));
                    let _ = slate::say(
                        b,
                        row,
                        &t("arrange.glyph.recent"),
                        W::SemiBold,
                        11.0,
                        ink.ink3,
                        Align2::LEFT_CENTER,
                        &s,
                    );
                });
                y += s.s(16.0);
                for (i, g) in recent.iter().enumerate() {
                    let r = Rect::from_min_size(
                        pos2(left + s.s((CELL + GAP) * i as f32), y),
                        vec2(s.s(CELL), s.s(CELL)),
                    );
                    let resp =
                        ui.interact(r, Id::new(("arrange-glyph-recent", g.id)), Sense::click());
                    drawn.push((Some(g.id), r));
                    let hov = resp.hovered();
                    kit::with_brush(ui.painter(), |b| {
                        cell(ui, b, &s, &ink, r, *g, chosen == Some(g.id), hov)
                    });
                    if hov {
                        hovered_name = Some(g.name());
                    }
                    if resp.clicked() {
                        pick = Some(Some(g.id));
                    }
                }
                y += s.s(CELL + 8.0);
            }
            kit::with_brush(ui.painter(), |b| {
                b.rect(
                    b.snap_rect(Rect::from_min_size(
                        pos2(left, y),
                        vec2(right - left, s.s(1.0)),
                    )),
                    kit::Fill::Solid(ink.edge),
                );
            });
            y += s.s(9.0);
            // The view: the families (or what search found), scrolled.
            let view =
                Rect::from_min_max(pos2(rect.left(), y), pos2(rect.right(), y + s.s(view_h)));
            let body = lines(&app.arrangement.glyphs.search);
            let total: f32 = body.iter().map(|l| s.s(line_height(l))).sum::<f32>() + s.s(6.0);
            let max = (total - view.height()).max(0.0);
            let hover_view = ui.rect_contains_pointer(view);
            if hover_view {
                let d = ui.input(|i| i.smooth_scroll_delta.y);
                app.arrangement.glyphs.scroll -= d;
            }
            let scroll = app.arrangement.glyphs.scroll.clamp(0.0, max);
            let clip = ui.painter().with_clip_rect(view);
            let mut ly = view.top() - scroll;
            for l in &body {
                let lh = s.s(line_height(l));
                if ly + lh >= view.top() && ly <= view.bottom() {
                    match l {
                        Line::Title(title, sub) => kit::with_brush(&clip, |b| {
                            let r =
                                Rect::from_min_max(pos2(left, ly), pos2(right, ly + lh - s.s(2.0)));
                            let (wt, size) = if *sub {
                                (W::Regular, 10.0)
                            } else {
                                (W::SemiBold, 11.0)
                            };
                            let _ = slate::say(
                                b,
                                r,
                                title,
                                wt,
                                size,
                                ink.ink3,
                                Align2::LEFT_BOTTOM,
                                &s,
                            );
                        }),
                        Line::Empty => kit::with_brush(&clip, |b| {
                            let r = Rect::from_min_max(pos2(left, ly), pos2(right, ly + lh));
                            let _ = slate::say(
                                b,
                                r,
                                &t("arrange.glyph.nothing"),
                                W::Regular,
                                11.0,
                                ink.ink3,
                                Align2::LEFT_CENTER,
                                &s,
                            );
                        }),
                        Line::Cells(row) => {
                            for (i, g) in row.iter().enumerate() {
                                let r = Rect::from_min_size(
                                    pos2(left + s.s((CELL + GAP) * i as f32), ly),
                                    vec2(s.s(CELL), s.s(CELL)),
                                );
                                let seen = r.intersect(view);
                                let resp = (seen.height() > s.s(4.0)).then(|| {
                                    ui.interact(
                                        seen,
                                        Id::new(("arrange-glyph", g.id)),
                                        Sense::click(),
                                    )
                                });
                                if seen.height() >= r.height() - 0.5 {
                                    drawn.push((Some(g.id), r));
                                }
                                let hov = resp.as_ref().is_some_and(|r| r.hovered());
                                kit::with_brush(&clip, |b| {
                                    cell(ui, b, &s, &ink, r, *g, chosen == Some(g.id), hov)
                                });
                                if hov {
                                    hovered_name = Some(g.name());
                                }
                                if resp.is_some_and(|r| r.clicked()) {
                                    pick = Some(Some(g.id));
                                }
                            }
                        }
                    }
                }
                ly += lh;
            }
            if max > 0.0 {
                let bar = Rect::from_min_max(
                    pos2(rect.right() - s.s(7.0), view.top()),
                    pos2(rect.right() - s.s(3.0), view.bottom()),
                );
                let mut start = scroll / total;
                let len = view.height() / total;
                kit::widgets::scrollbar(ui, bar, Id::new("arrange-glyph-scroll"), &mut start, len);
                app.arrangement.glyphs.scroll = (start * total).clamp(0.0, max);
            } else {
                app.arrangement.glyphs.scroll = scroll;
            }
            // The foot: what the icon does, and the name of the one under the pointer.
            let fy = view.bottom();
            kit::with_brush(ui.painter(), |b| {
                b.rect(
                    b.snap_rect(Rect::from_min_size(
                        pos2(rect.left() + s.s(1.0), fy),
                        vec2(rect.width() - s.s(2.0), s.s(1.0)),
                    )),
                    kit::Fill::Solid(ink.edge),
                );
                let row =
                    Rect::from_min_max(pos2(left, fy + s.s(8.0)), pos2(right, fy + s.s(26.0)));
                match hovered_name {
                    Some(n) if !n.is_empty() => {
                        let _ = slate::say(
                            b,
                            row,
                            n,
                            W::Medium,
                            11.0,
                            ink.ink1,
                            Align2::LEFT_CENTER,
                            &s,
                        );
                    }
                    _ => {
                        let _ = slate::say(
                            b,
                            row,
                            &t("arrange.glyph.colour"),
                            W::Regular,
                            10.0,
                            ink.ink3,
                            Align2::LEFT_CENTER,
                            &s,
                        );
                    }
                }
            });
            if let Some(n) = hovered_name.filter(|n| !n.is_empty()) {
                kit::hint::set_text(ui.ctx(), n, "", kit::hint::Caps::NONE);
            }
        });
    app.arrangement.glyphs.drawn = drawn;
    if let Some(choice) = pick {
        set(app, track, choice);
        close = true;
    }
    let pass = ctx.cumulative_pass_nr();
    let away = ctx.input(|i| i.pointer.any_pressed())
        && ctx
            .input(|i| i.pointer.interact_pos())
            .is_some_and(|p| !area.response.rect.contains(p));
    if pass > app.arrangement.glyphs.opened && away {
        close = true;
    }
    if close {
        app.arrangement.glyphs.open = None;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_library_is_set_6_whole() {
        crate::i18n::set_thread_locale(crate::i18n::Locale::En);
        let lib = library();
        assert_eq!(lib.icons.len(), 316, "316 icons");
        let families = lib.sections.iter().filter(|s| s.sub.is_none()).count();
        assert_eq!(families, 17, "the owner's 17 families");
        assert_eq!(lib.sections[0].family, "drums");
        assert_eq!(lib.sections.last().unwrap().family, "letters_and_numbers");
        for sec in &lib.sections {
            assert!(!sec.icons.is_empty(), "{} is empty", sec.key);
            assert_ne!(t(&sec.key), sec.key, "{} has no title", sec.key);
        }
        // Every icon sits in a family, and has its two names.
        for (n, i) in lib.icons.iter().enumerate() {
            assert!(
                lib.sections.iter().any(|s| s.icons.contains(&(n as u16))),
                "{} is in no family",
                i.id
            );
            assert!(!i.en.is_empty() && !i.es.is_empty(), "{} unnamed", i.id);
            // What the project accepts (ADR 0113: lower case, digits, hyphens, 48 at most).
            assert!(
                i.id.len() <= 48
                    && i.id
                        .chars()
                        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                "{}: not an id the project keeps",
                i.id
            );
        }
    }

    #[test]
    fn every_icon_is_drawn_at_every_size_and_inks_its_canvas() {
        let t = crate::theme_slate::slate_night_tokens();
        let ink = Inks {
            main: t.text,
            second: t.text_dim,
            rec: t.danger,
            cut: t.well,
        };
        for g in all() {
            for size in SIZES {
                let body = drawing(g, size).unwrap_or_else(|| panic!("{} at {size} px", g.id));
                let doc = kit::icons::document(body, size, &ink);
                assert!(
                    !doc.contains("var("),
                    "{} {size}: an ink left unnamed",
                    g.id
                );
                let mut pix = tiny_skia::Pixmap::new(size.into(), size.into()).unwrap();
                kit::icons::raster(&doc, &mut pix);
                let inked = pix.pixels().iter().filter(|p| p.alpha() > 0).count();
                assert!(inked > 4, "{} {size}: {inked} pixels inked", g.id);
            }
        }
    }

    fn first(q: &str, n: usize) -> Vec<&'static str> {
        matching(q).iter().take(n).map(|g| g.id).collect()
    }

    #[test]
    fn search_finds_english_spanish_and_aliases() {
        assert_eq!(first("bombo", 1), ["kick"]);
        assert_eq!(first("kick", 1), ["kick"]);
        assert_eq!(first("clave de sol", 1), ["treble-clef"]);
        assert_eq!(first("treble", 1), ["treble-clef"]);
        assert_eq!(first("G clef", 1), ["treble-clef"]);
        assert!(
            first("sol", 3).contains(&"treble-clef"),
            "{:?}",
            first("sol", 3)
        );
        assert_eq!(first("clave de do", 1), ["c-clef"]);
        assert_eq!(first("guitarra de 12 cuerdas", 1), ["guitar12"]);
        // Accents and case aside.
        assert_eq!(first("guiro", 1), ["guiro"]);
        assert_eq!(first("GÜIRO", 1), ["guiro"]);
        assert_eq!(first("cruz", 1), ["cross"]);
        assert!(first("ride", 2).contains(&"ride"));
        assert!(first("platillo", 12).contains(&"crash"));
        assert!(matching("zzzz-nothing").is_empty());
        assert_eq!(matching("").len(), 316);
    }

    #[test]
    fn an_icon_is_found_by_id_and_old_ids_keep_their_picture() {
        assert_eq!(by_id("treble-clef").map(|g| g.id), Some("treble-clef"));
        assert_eq!(by_id("drums").map(|g| g.id), Some("drumkit"));
        assert_eq!(by_id("no-such-icon"), None);
        let g = by_id("bass").unwrap();
        crate::i18n::set_thread_locale(crate::i18n::Locale::En);
        assert_eq!(g.name_in("notation"), "bass clef");
        assert_eq!(g.name(), "bass (synth)");
    }

    #[test]
    fn a_box_takes_the_largest_drawing_that_fits() {
        assert_eq!(size_for(10.0), 12);
        assert_eq!(size_for(16.0), 16);
        assert_eq!(size_for(17.0), 16);
        assert_eq!(size_for(17.9), 18);
        assert_eq!(size_for(20.0), 20);
        assert_eq!(size_for(30.0), 30);
        assert_eq!(size_for(100.0), 36);
    }
}
